INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p89720-ee463', 'stk-user15', 'EE 463', 'info', '{"desc": "حياك الله\n\nأنا أخذت 463 مع د.شكري\n\nالصراحة …\n\nالرجال شريح و المادة مهمة في التوظيف … يعني الهدف تفهمها\n\nبالنسبة لاختباراته ( مو صعبه مره و لا هي سهلة ) … وبالقريد (حقاني )\n\nيعني المادة كانت ممتعة جداً\n\nبالنسبة 465 ( خطوط النقل ) مادة “أكل عليها الدهر و شرب” يعني لو تاخذ ماده ثانيه أحسن لك\n\nو يعطيكك العافية", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-463/49703/3", "user": "user15", "ts": 1139395273000, "tid": 49703, "pn": 3}}', 1139395273000, 1794826858, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
